from fractions import Fraction


def best_average(a: list[int], k: int) -> list[int]:
    prefix = [0]
    for x in a:
        prefix.append(prefix[-1] + x)

    best_num = 0
    best_den = 1
    candidates = []

    for end in range(k, len(a) + 1):
        start = end - k

        # Maintain the lower convex hull of eligible prefix points
        # (index, prefix[index]).
        while len(candidates) >= 2:
            i, j = candidates[-2], candidates[-1]
            if (prefix[j] - prefix[i]) * (start - j) >= (
                prefix[start] - prefix[j]
            ) * (j - i):
                candidates.pop()
            else:
                break
        candidates.append(start)

        # The maximum average ending at end is the minimum slope
        # from an eligible prefix point to (end, prefix[end]).
        while len(candidates) >= 2:
            i, j = candidates[0], candidates[1]
            if (prefix[end] - prefix[i]) * (end - j) <= (
                prefix[end] - prefix[j]
            ) * (end - i):
                candidates.pop(0)
            else:
                break

        i = candidates[0]
        num = prefix[end] - prefix[i]
        den = end - i
        if num * best_den > best_num * den:
            best_num, best_den = num, den

    f = Fraction(best_num, best_den)
    return [f.numerator, f.denominator]
